declare(strict_types=1);
ini_set('session.use_strict_mode','1');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']);session_start();
require dirname(__DIR__).'/private/bootstrap.php';
$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals(csrf(),(string)($_POST['csrf']??''))){http_response_code(403);exit('Invalid CSRF');}
 $action=(string)($_POST['action']??'');
 try{
 if($action==='login'){
  $valid=hash_equals(strtolower((string)$c['admin_email']),strtolower(trim((string)($_POST['email']??''))))&&password_verify((string)($_POST['password']??''),(string)$c['admin_password_hash']);
  if($valid){session_regenerate_id(true);$_SESSION['auth']=true;redirect();}else{$error='Invalid login.';sleep(1);}
 }elseif($action==='logout'){require_auth();$_SESSION=[];session_destroy();redirect();}
 else{require_auth();
 if($action==='company'){$name=trim((string)($_POST['name']??''));$domain=clean_domain((string)($_POST['domain']??''));if(!$domain||$name==='')throw new RuntimeException('Valid company name and domain required');$s=db()->prepare('INSERT INTO companies(name,domain,country,industry,source_url) VALUES(?,?,?,?,?)');$s->execute([mb_substr($name,0,255),$domain,mb_substr((string)($_POST['country']??''),0,100),mb_substr((string)($_POST['industry']??''),0,120),mb_substr((string)($_POST['source_url']??''),0,1000)]);audit('company_added',$domain);$notice='Company saved.';}
 if($action==='discover'){$country=(string)($_POST['country']??'');$industry=(string)($_POST['industry']??'');if(!in_array($country,['Saudi Arabia','UAE','Qatar','Kuwait','Oman','Bahrain','Worldwide'],true)||mb_strlen($industry)>100)throw new RuntimeException('Invalid discovery parameters');[$found,$added]=discover($country,$industry?:'construction');$notice="Search results: $found domains found, $added new records.";}
 if($action==='contact'){$id=(int)($_POST['company_id']??0);$email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Valid email required');$s=db()->prepare('INSERT INTO contacts(company_id,email,full_name,role_title) VALUES(?,?,?,?)');$s->execute([$id,$email,mb_substr((string)($_POST['full_name']??''),0,255),mb_substr((string)($_POST['role_title']??''),0,150)]);audit('contact_added',$email);$notice='Contact added. Permission status defaults to unknown.';}
 if($action==='permission'){$id=(int)($_POST['id']??0);$status=(string)($_POST['permission_status']??'unknown');$evidence=trim((string)($_POST['permission_evidence']??''));$basis=trim((string)($_POST['permission_basis']??''));if(!in_array($status,['unknown','confirmed','revoked'],true))throw new RuntimeException('Invalid permission');if(!in_array((string)($_POST['validation_status']??'unverified'),['unverified','valid','invalid'],true))throw new RuntimeException('Invalid validation status');if($status==='confirmed'&&($evidence===''||$basis===''))throw new RuntimeException('Documented permission basis and evidence required');$s=db()->prepare('UPDATE contacts SET permission_status=?,permission_basis=?,permission_evidence=?,permission_at=NOW(),validation_status=? WHERE id=?');$s->execute([$status,$basis,$evidence,(string)($_POST['validation_status']??'unverified'),$id]);if($status==='revoked'){$x=db()->prepare('INSERT IGNORE INTO suppression(email,reason) SELECT email,? FROM contacts WHERE id=?');$x->execute(['Permission revoked',$id]);}audit('permission_updated',(string)$id);$notice='Contact review updated.';}
 if($action==='draft'){$id=(int)($_POST['contact_id']??0);$s=db()->prepare('SELECT ct.*,co.name,co.industry FROM contacts ct JOIN companies co ON co.id=ct.company_id WHERE ct.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Contact not found');[$subject,$body]=ai_proposal_text($r,$r);$s=db()->prepare('INSERT INTO proposals(company_id,contact_id,subject,body) VALUES(?,?,?,?)');$s->execute([$r['company_id'],$id,$subject,$body]);audit('draft_created',(string)$id);$notice='Draft generated. Edit before approval.';}
 if($action==='proposal'){$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'draft');$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['body']??''));if(!in_array($status,['draft','approved','cancelled'],true)||$subject===''||$body==='')throw new RuntimeException('Invalid proposal');$s=db()->prepare('SELECT ct.permission_status,ct.permission_basis,ct.permission_evidence,ct.validation_status,ct.email FROM proposals p JOIN contacts ct ON ct.id=p.contact_id WHERE p.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Missing proposal');if($status==='approved'&&($r['permission_status']!=='confirmed'||trim((string)($r['permission_basis']??''))===''||$r['validation_status']!=='valid'||trim((string)$r['permission_evidence'])===''||(int)db()->query("SELECT COUNT(*) FROM suppression WHERE email=".db()->quote($r['email']))->fetchColumn()>0))throw new RuntimeException('Contact lacks verified permission. Cannot approve.');$s=db()->prepare("UPDATE proposals SET subject=?,body=?,status=?,approved_at=IF(?='approved',NOW(),NULL) WHERE id=? AND status IN ('draft','approved')");$s->execute([mb_substr($subject,0,255),$body,$status,$status,$id]);audit('proposal_review',"$id $status");$notice='Proposal updated.';}
 if($action==='send') {[$sent,$failed]=send_approved(10);$notice="Provider accepted $sent emails; $failed need manual review.";}
 if($action==='activity'){$s=db()->prepare('INSERT INTO activities(company_id,note,next_action) VALUES(?,?,?)');$s->execute([(int)($_POST['company_id']??0),trim((string)($_POST['note']??'')),($_POST['next_action']??'')?:null]);$notice='CRM note saved.';}
 }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$auth=!empty($_SESSION['auth']);$tab=(string)($_GET['tab']??'dashboard');$tabs=['dashboard'=>'Overview','companies'=>'Companies','discovery'=>'Discovery','contacts'=>'Contacts','proposals'=>'Proposals','crm'=>'CRM','logs'=>'Activity','help'=>'Help & Guide'];if(!isset($tabs[$tab]))$tab='dashboard';
if($auth&&isset($_GET['export'])){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="gjw_companies.csv"');$f=fopen('php://output','w');fputcsv($f,['Company','Domain','Country','Industry','Source','Hiring Signal','Status']);foreach(db()->query('SELECT name,domain,country,industry,source_url,hiring_signal,status FROM companies ORDER BY id DESC') as $r){fputcsv($f,array_map(fn($v)=>preg_match('/^[=+@\-\t\r]/',(string)$v)?"'".$v:$v,array_values($r)));}fclose($f);exit;}
