 if($market!==''){$where[]='country=?';$params[]=$market;}
 $whereSql=$where?' WHERE '.implode(' AND ',$where):'';
 $countStmt=db()->prepare('SELECT COUNT(*) FROM companies'.$whereSql);$countStmt->execute($params);$total=(int)$countStmt->fetchColumn();
