<?php elseif($tab==='proposals'):?><section><h2>Generate Personalized Draft</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="draft"><div><label>Contact</label><select name="contact_id"><?php foreach(fetch_all('SELECT id,email FROM contacts ORDER BY id DESC LIMIT 500') as $r):?><option value="<?=h($r['id'])?>"><?=h($r['email'])?></option><?php endforeach;?></select></div><div><label>&nbsp;</label><button>Generate Draft</button></div></form><p class="note">Uses AI when configured, otherwise an editable safe template. Review every claim and add verified company contact details before approval.</p></section><section><h2>Review & Approval</h2><?php foreach(fetch_all("SELECT p.*,ct.email FROM proposals p JOIN contacts ct ON ct.id=p.contact_id ORDER BY p.id DESC LIMIT 40") as $r):?><form method="post" style="border-bottom:1px solid #e3ebef;padding:14px 0"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="proposal"><input type="hidden" name="id" value="<?=h($r['id'])?>"><strong><?=h($r['email'])?></strong> <span class="pill"><?=h($r['status'])?></span><p><label>Subject</label><input name="subject" value="<?=h($r['subject'])?>" required></p><p><label>Body</label><textarea name="body" rows="7" required><?=h($r['body'])?></textarea></p><?php if(in_array($r['status'],['draft','approved'],true)):?><div class="grid"><div><label>Action</label><select name="status"><option value="draft">Save draft</option><option value="approved">Approve (permission required)</option><option value="cancelled">Cancel</option></select></div><div><label>&nbsp;</label><button>Save</button></div></div><?php endif;?></form><?php endforeach;?></section><section><h2>Send Approved Queue</h2><p class="note">Brevo API integration. Sends max 10 per manual batch, capped by daily limit. Only confirmed-permission, manually validated contacts. Delivery acceptance is not inbox placement.</p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="send"><button>Send Eligible Approved Emails</button></form></section>
<?php elseif($tab==='crm'):?><section><h2>Add CRM Activity</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="activity"><div><label>Company</label><select name="company_id"><?php foreach(fetch_all('SELECT id,name FROM companies ORDER BY name LIMIT 500') as $r):?><option value="<?=h($r['id'])?>"><?=h($r['name'])?></option><?php endforeach;?></select></div><div><label>Next follow-up</label><input type="date" name="next_action"></div><div><label>Notes</label><textarea name="note" required></textarea></div><div><label>&nbsp;</label><button>Save Activity</button></div></form></section><section><h2>Recent CRM Notes</h2><?php foreach(fetch_all('SELECT a.*,co.name FROM activities a JOIN companies co ON co.id=a.company_id ORDER BY a.id DESC LIMIT 40') as $r):?><p><strong><?=h($r['name'])?></strong> — <?=h($r['note'])?> <small><?=h($r['next_action'])?></small></p><?php endforeach;?></section>
<?php elseif($tab==='help'):?><section><h2>Help &amp; Getting Started</h2><p class="note">Follow these steps in order. No programming knowledge is required to operate the dashboard after installation.</p><div class="helpgrid"><article><h3>Step 1 — Find employers</h3><p>Open <a href="?tab=discovery">Discovery</a>. Choose a country and industry. Discovery needs a configured licensed search API and can return irrelevant results; review each company.</p></article><article><h3>Step 2 — Manage companies</h3><p>Use <a href="?tab=companies">Companies</a> to add an employer or search records. A company website domain helps prevent duplicates.</p></article><article><h3>Step 3 — Review contacts</h3><p>In <a href="?tab=contacts">Contacts</a>, check each address and record actual permission evidence. Never mark an address as verified merely because it is published online.</p></article><article><h3>Step 4 — Prepare proposal</h3><p>Go to <a href="?tab=proposals">Proposals</a>. Generate a draft, check company-specific facts, and edit the subject and body before approval.</p></article><article><h3>Step 5 — Send eligible proposals</h3><p>The send queue only processes approved proposals with confirmed permission and validation. Sending requires a configured and authorized email provider.</p></article><article><h3>Step 6 — Follow up</h3><p>Use <a href="?tab=crm">CRM</a> to save notes and follow-up dates. Check <a href="?tab=logs">Activity</a> for sending records and errors.</p></article></div></section><section><h2>Frequently Asked Questions</h2><details><summary>Will it automatically find 100 real employers every day?</summary><p>100 is a discovery target, not a guaranteed result. The quality and quantity depend on licensed sources, API quota and available evidence.</p></details><details><summary>Will the software send to every email it finds?</summary><p>No. Publicly visible emails are not automatically eligible. Contact permission and provider rules must be satisfied.</p></details><details><summary>Can staff use it from a mobile phone?</summary><p>The interface adapts to mobile browsers, but full deployment, access controls and mobile device testing are still required.</p></details><details><summary>What if the internet or API stops?</summary><p>Check Activity logs. An interrupted task may need review; never resend a message without checking its delivery state.</p></details><details><summary>Is this production-ready?</summary><p>No. Live Hostinger deployment, database testing, API authorization, security hardening and real-world delivery tests are required before production use.</p></details></section>
<?php elseif($tab==='logs'):?><section><h2>Audit Log</h2><div class="scroll"><table><tr><th>Action</th><th>Detail</th><th>Time</th></tr><?php foreach(fetch_all('SELECT * FROM audit_log ORDER BY id DESC LIMIT 100') as $r):?><tr><td><?=h($r['action'])?></td><td><?=h($r['detail'])?></td><td><?=h($r['created_at'])?></td></tr><?php endforeach;?></table></div></section><section><h2>Sending Events</h2><div class="scroll"><table><tr><th>Proposal</th><th>Event</th><th>Detail</th></tr><?php foreach(fetch_all('SELECT * FROM mail_events ORDER BY id DESC LIMIT 50') as $r):?><tr><td><?=h($r['proposal_id'])?></td><td><?=h($r['event_type'])?></td><td><?=h($r['detail'])?></td></tr><?php endforeach;?></table></div></section><?php endif;?>
<?php endif;?></main><footer>Gulf Job Works · Employer Connect AI · Developed for simple, responsible recruitment outreach</footer></body></html>
